_initTabTrap() {
  EventHandler.on(this._element, 'keydown.tab', event => this._handleTab(event))
}

_removeTabTrap() {
  EventHandler.off(this._element, 'keydown.tab')
}

_handleTab(event) {
  if (event.key !== 'Tab') return
  const focusable = SelectorEngine.find(
    'a[href], area[href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), button:not([disabled]), iframe, object, embed, *[tabindex]:not([tabindex="-1"]), *[contenteditable]',
    this._element
  )
  const filtered = focusable.filter(el => !el.hasAttribute('disabled') && el.getAttribute('tabindex') !== '-1')
  if (filtered.length === 0) {
    event.preventDefault()
    return
  }
  const first = filtered[0]
  const last = filtered[filtered.length - 1]
  if (event.shiftKey) {
    if (document.activeElement === first) {
      event.preventDefault()
      last.focus()
    }
  } else {
    if (document.activeElement === last) {
      event.preventDefault()
      first.focus()
    }
  }
}

